{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    # Build maps
    nodes_by_id = {n['id']: n for n in nodes}
    parent_of = {n['id']: n['parent'] for n in nodes}
    children_of = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children_of.setdefault(pid, []).append(n['id'])

    # Set of currently present node IDs
    present = set(nodes_by_id.keys())

    # Symbol counts
    symbol_count = {}
    for n in nodes:
        s = n['symbol']
        symbol_count[s] = symbol_count.get(s, 0) + 1

    # Order: deeper first, then tie by id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    removed = []

    for node in sorted_nodes:
        nid = node['id']
        if nid not in present:
            continue
        # Never remove root
        if node['parent'] is None:
            continue
        # Never remove a node with required symbol
        if node['symbol'] in required_symbols:
            continue
        # Never remove non-removable node
        if not node['removable']:
            continue
        # Never remove a node that has any retained children (still present)
        has_retained_child = False
        for child_id in children_of.get(nid, []):
            if child_id in present:
                has_retained_child = True
                break
        if has_retained_child:
            continue

        # Compute the set of nodes that would be removed (this node + its entire retained subtree)
        removal_set = set()
        stack = [nid]
        while stack:
            cid = stack.pop()
            if cid in removal_set:
                continue
            removal_set.add(cid)
            for child_id in children_of.get(cid, []):
                if child_id in present:
                    stack.append(child_id)

        # Compute symbol loss
        removal_symbols = {}
        for rid in removal_set:
            s = nodes_by_id[rid]['symbol']
            removal_symbols[s] = removal_symbols.get(s, 0) + 1

        # Check if any required symbol would become absent
        abort = False
        for req_sym in required_symbols:
            current = symbol_count.get(req_sym, 0)
            lost = removal_symbols.get(req_sym, 0)
            if current - lost <= 0:
                abort = True
                break
        if abort:
            continue

        # Perform removal
        for rid in removal_set:
            present.remove(rid)
            s = nodes_by_id[rid]['symbol']
            symbol_count[s] -= 1
        removed.append(nid)

    retained = sorted(present)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained
    }"
}
